public function eliminarArchivo(InformeIntermedioProyecto $informe, User $user): void
{
    abort_unless($informe->proyecto->usuarioPuedeGestionarInformeFinal($user), 403);

    if ($informe->estado !== InformeIntermedioProyecto::ESTADO_BORRADOR || $informe->documento_proyecto_id) {
        throw new \RuntimeException('El PDF solo puede eliminarse mientras el Informe Intermedio está en borrador.');
    }

    $path = $informe->archivo_pdf;

    DB::transaction(fn () => $informe->delete());
    Storage::disk('local')->delete($path);
}

public function enviar(
    InformeIntermedioProyecto $informe,
    User $user,
    array $usuariosElegidosPorEtapa = []
): DocumentoProyecto {
    abort_unless($informe->proyecto->usuarioPuedeGestionarInformeFinal($user), 403);
    $this->validarArchivoPersistido($informe);

    return DB::transaction(function () use ($informe, $user, $usuariosElegidosPorEtapa): DocumentoProyecto {
        $bloqueado = InformeIntermedioProyecto::query()->whereKey($informe->id)->lockForUpdate()->firstOrFail();
        $proyecto = Proyecto::query()->whereKey($bloqueado->proyecto_id)->lockForUpdate()->firstOrFail();
        $bloqueado->setRelation('proyecto', $proyecto);

        if (! in_array($bloqueado->estado, [
            InformeIntermedioProyecto::ESTADO_BORRADOR,
            InformeIntermedioProyecto::ESTADO_SUBSANACION,
        ], true)) {
            throw new \RuntimeException('El Informe Intermedio ya fue enviado.');
        }

        if ($bloqueado->estado === InformeIntermedioProyecto::ESTADO_BORRADOR) {
            if (! $this->estaDisponible($proyecto, $user)) {
                throw new \RuntimeException('El Informe Intermedio todavía no está disponible para este proyecto.');
            }

            $documento = $this->documentos->iniciar(
                $proyecto,
                'Informe Intermedio',
                $bloqueado->archivo_pdf,
                $user,
                $usuariosElegidosPorEtapa
            );
        } else {
            $documento = $bloqueado->documento;

            if (! $documento || $documento->estado?->tipoestado?->nombre !== 'Subsanacion') {
                throw new \RuntimeException('No existe una subsanación vigente para reenviar.');
            }

            $documento = $this->documentos->reenviarDesdeSubsanacion(
                $proyecto,
                $documento,
                $bloqueado->archivo_pdf,
                $user
            );
        }

        $firmaActual = $this->firmaActual($proyecto, $documento);
        $bloqueado->update([
            'documento_proyecto_id' => $documento->id,
            'estado' => InformeIntermedioProyecto::ESTADO_EN_REVISION,
            'etapa_actual_id' => $firmaActual?->flujo_aprobacion_etapa_id,
            'etapa_retorno_id' => null,
            'enviado_por' => $user->id,
            'fecha_envio' => now(),
            'observaciones' => null,
        ]);

        return $documento->fresh();
    });
}

        $informe->proyecto,
        $user,
        '[Cierre INF-001] Informe final completado y listo para envío.'
    );
}

public function enviarInformeFinal(
    InformeFinalProyecto $informe,
    User $user,
    array $usuariosElegidosPorEtapa = []
): DocumentoProyecto
{
    abort_unless($this->puedeEnviarInformeFinal($informe, $user), 403);
    $this->validator->validateForCompletion($informe->fresh());

    $contenido = $this->pdfGenerator->content($informe->fresh());
    $ciclo = max(1, (int) $informe->documentoCierre?->firma_documento()->max('revision_ciclo') + 1);
    $path = sprintf(
        'documentos/informes-finales/inf-001-%d-ciclo-%d-%s.pdf',
        $informe->id,
        $ciclo,
        Str::uuid()
    );
    if (! Storage::disk('public')->put($path, $contenido)) {
        throw new \RuntimeException('No se pudo almacenar el PDF canónico del informe final.');
    }

    try {
        return DB::transaction(function () use ($informe, $user, $path, $usuariosElegidosPorEtapa): DocumentoProyecto {
            $informeBloqueado = InformeFinalProyecto::query()->whereKey($informe->id)->lockForUpdate()->firstOrFail();
            $proyecto = Proyecto::query()->whereKey($informeBloqueado->proyecto_id)->lockForUpdate()->firstOrFail();
            $informeBloqueado->setRelation('proyecto', $proyecto);

            if (! $this->puedeEnviarInformeFinal($informeBloqueado, $user)) {
                throw new \RuntimeException('El informe final ya no se encuentra disponible para envío.');
            }

            $documento = $proyecto->documentos()
                ->where('tipo_documento', 'Informe Final')
                ->lockForUpdate()
                ->first();

            if (! $documento) {
                return $this->documentos->iniciar(
                    $proyecto,
                    'Informe Final',
                    $path,
                    $user,
                    $usuariosElegidosPorEtapa
                );
            }

            if ($documento->estado?->tipoestado?->nombre !== 'Subsanacion') {
                throw new \RuntimeException('El informe final ya inició su flujo de cierre.');
            }

            return $this->documentos->reenviarDesdeSubsanacion($proyecto, $documento, $path, $user);
        });
    } catch (\Throwable $exception) {
        Storage::disk('public')->delete($path);
        throw $exception;
    }
}

public function resumenCierre(Proyecto $proyecto, ?User $user): array
{
    $relacionesInforme = [
        'documentoCierre.estadoActual.tipoestado',
        'documentoCierre.estado_documento.tipoestado',
        'documentoCierre.firma_documento.empleado',
    ];
    if (Schema::hasTable('constancias_finalizacion_proyecto')) {
        $relacionesInforme[] = 'constanciaFinalizacion';
    }
    $informe = $proyecto->informeFinalInf001()->with($relacionesInforme)->first();

    $this->validate(['informeIntermedioFile' => 'required|file|mimes:pdf|max:20480']);

    try {
        $workflow->guardarArchivo($this->proyecto->fresh(), $this->informeIntermedioFile, auth()->user());
    } catch (\Throwable $e) {
        Notification::make()->title('No se pudo guardar el informe')->body($e->getMessage())->danger()->send();
        return;
    }

    $this->informeIntermedioModal = false;
    $this->informeIntermedioFile = null;

    $this->proyecto = $this->proyecto->fresh();
    Notification::make()->title('PDF guardado')->body('El Informe Intermedio quedó guardado como borrador.')->success()->send();
}

public function enviarInformeIntermedio(InformeIntermedioProyectoWorkflowService $workflow): void
{
    $informe = $this->proyecto->informeIntermedio()->firstOrFail();

    try {
        $workflow->enviar($informe, auth()->user(), $this->destinatariosIntermedio);
        $this->proyecto = $this->proyecto->fresh();
        Notification::make()->title('Informe enviado')->body('El Informe Intermedio inició su flujo de revisión.')->success()->send();
    } catch (\Throwable $e) {
        Notification::make()->title('No se pudo enviar el informe')->body($e->getMessage())->danger()->send();
    }
}

public function eliminarInformeIntermedio(InformeIntermedioProyectoWorkflowService $workflow): void
{
    $informe = $this->proyecto->informeIntermedio()->firstOrFail();

    try {
        $workflow->eliminarArchivo($informe, auth()->user());
        $this->proyecto = $this->proyecto->fresh();
        Notification::make()->title('PDF eliminado')->body('El borrador del Informe Intermedio fue eliminado.')->success()->send();
    } catch (\Throwable $e) {
        Notification::make()->title('No se pudo eliminar el PDF')->body($e->getMessage())->danger()->send();
    }
}

public function crearInformeFinal(InformeFinalProyectoWorkflowService $workflow)
{
    $informe = $workflow->crearInformeFinal($this->proyecto->fresh(), auth()->user());

    return $this->redirectRoute('proyectos.informe-final', ['proyecto' => $informe->proyecto_id]);
}

public function enviarInformeFinal(InformeFinalProyectoWorkflowService $workflow): void
{
    $informe = $this->proyecto->informeFinalInf001()->firstOrFail();
    abort_unless($workflow->puedeEnviarInformeFinal($informe, auth()->user()), 403);

    try {
        $workflow->enviarInformeFinal($informe, auth()->user(), $this->destinatariosCierre);
        $this->proyecto = $this->proyecto->fresh();
        Notification::make()
            ->title('Informe final enviado')
            ->body('El INF-001 inició el flujo de cierre del proyecto.')
            ->success()
            ->send();
    } catch (\Throwable $exception) {
        Notification::make()
            ->title('No se pudo enviar el informe final')
            ->body($exception->getMessage())
            ->danger()
            ->send();
    }
}

