            // Firmas de documentos (informes, etc.)
            else if (
                ($firma->firmable_type == \App\Models\Proyecto\DocumentoProyecto::class &&
                    ($firma->cargo_firma->tipo_estado_id == $firma->documento_proyecto->estado->tipoestado->id))
