   467	    {
   468	        $ultimoCiclo = $this->obtenerUltimoCiclo($registro);
   469	        $plan = $this->planDeUltimoCiclo($registro);
   470	
   471	        /** @var FirmaProyecto $firmaRechazada */
   472	        $firmaRechazada = $plan->rejectedStage['source'];
   473	        $empleadosPorEtapa = $this->resolverEmpleadosHistoricosParaReanudacion(
   474	            $registro,
   475	            $plan->stages,
   476	            $firmaRechazada,
   477	            $reemplazosHistoricos
   478	        );
   479	        $flujo = FlujoAprobacion::query()->find($firmaRechazada->flujo_aprobacion_id);
   480	
   481	        if (! $flujo || $flujo->proceso !== PpsServicioSocial::PROCESO_FLUJO) {
   482	            throw new RuntimeException('El historial no contiene un flujo PPS/SS válido para reanudar.');
   483	        }
   484	
