   490	    private function planDeUltimoCiclo(PpsServicioSocial $registro): \App\Services\Workflow\WorkflowResumptionPlan
   491	    {
   492	        $ultimoCiclo = $this->obtenerUltimoCiclo($registro);
   493	        $firmasCiclo = $registro->firmasDeEtapa()
   494	            ->where('flujo_aprobacion_id', $registro->flujo_aprobacion_id)
   495	            ->where('revision_ciclo', $ultimoCiclo)
   496	            ->whereNotNull('flujo_aprobacion_etapa_id')
   497	            ->whereNull('deleted_at')
   498	            ->orderBy('orden_revision')
   499	            ->orderBy('id')
   500	            ->get();
   501	
   502	        return app(WorkflowResumptionPolicy::class)->plan(
   503	            $firmasCiclo
   504	                ->reject(fn (FirmaProyecto $firma): bool => $firma->estado_revision === 'Anulado')
   505	                ->map(fn (FirmaProyecto $firma): array => [
   506	                    'stage_id' => (int) $firma->flujo_aprobacion_etapa_id,
   507	                    'order' => (int) $firma->orden_revision,
   508	                    'status' => match ($firma->estado_revision) {
   509	                        'Aprobado' => 'APPROVED',
   510	                        'Rechazado' => 'REJECTED',
   511	                        'Pendiente' => 'PENDING',
   512	                        default => 'INVALID',
   513	                    },
   514	                    'source' => $firma,
   515	                ])
   516	                ->values()
   517	        );
   518	    }
