  1477	    ): Collection {
  1478	        return DB::transaction(function () use ($firmaRechazada, $empleadosPorEtapa): Collection {
  1479	            self::query()->whereKey($this->id)->lockForUpdate()->firstOrFail();
  1480	
  1481	            $documento = $this->documentoDeFirmaDelProyecto($firmaRechazada);
  1482	
  1483	            if ($firmaRechazada->firmable_type === DocumentoProyecto::class) {
  1484	                if (! $documento) {
  1485	                    throw new \RuntimeException('La firma no pertenece al proyecto indicado.');
  1486	                }
  1487	
  1488	                DocumentoProyecto::query()->whereKey($documento->id)->lockForUpdate()->firstOrFail();
  1489	            }
  1490	
  1491	            $firmaBloqueada = FirmaProyecto::query()
  1492	                ->whereKey($firmaRechazada->id)
  1493	                ->lockForUpdate()
  1494	                ->first();
  1495	
  1496	            if (! $firmaBloqueada) {
  1497	                throw new \RuntimeException('La firma indicada no corresponde a una etapa rechazada.');
  1498	            }
  1499	
  1500	            $documento = $this->documentoDeFirmaDelProyecto($firmaBloqueada);
  1501	            $this->validarFirmaRechazadaParaNuevoCiclo($firmaBloqueada, $documento);
  1502	
  1503	            $firmasCiclo = $this->relacionFirmasDeEtapas($documento)
  1504	                ->where('flujo_aprobacion_id', $firmaBloqueada->flujo_aprobacion_id)
  1505	                ->where('revision_ciclo', $firmaBloqueada->revision_ciclo)
  1506	                ->whereNotNull('flujo_aprobacion_etapa_id')
  1507	                ->whereNull('deleted_at')
  1508	                ->lockForUpdate()
  1509	                ->orderBy('orden_revision')
  1510	                ->orderBy('id')
  1511	                ->get();
  1512	
  1513	            $this->validarFirmaRechazadaParaNuevoCiclo($firmaBloqueada->fresh(), $documento, $firmasCiclo);
  1514	
  1515	            $nuevoCiclo = (int) $firmaBloqueada->revision_ciclo + 1;
  1516	
  1517	            if ($this->existenFirmasDeCicloPorEtapa((int) $firmaBloqueada->flujo_aprobacion_id, $nuevoCiclo, $documento)) {
  1518	                throw new \RuntimeException('Ya existe el siguiente ciclo de revisión para este registro.');
  1519	            }
  1520	
  1521	            $firmasBase = $this->firmasBaseParaNuevoCicloDesdeRechazo($firmaBloqueada->fresh(), $firmasCiclo);
  1522	            $etapasCicloAnterior = $firmasCiclo
  1523	                ->pluck('flujo_aprobacion_etapa_id')
  1524	                ->map(fn ($id): int => (int) $id);
  1525	
  1526	            foreach (array_keys($empleadosPorEtapa) as $etapaAsignadaId) {
