  1541	            $relation = $this->relacionFirmasDeEtapas($documento);
  1542	
  1543	            $firmasCreadas = $firmasBase
  1544	                ->map(function (FirmaProyecto $firmaBase) use ($relation, $empleados, $nuevoCiclo): FirmaProyecto {
  1545	                    return $relation->create([
  1546	                        'empleado_id' => $empleados->get((int) $firmaBase->flujo_aprobacion_etapa_id)->id,
  1547	                        'cargo_firma_id' => $firmaBase->cargo_firma_id,
