481	            'flujo_id' => $accion->flujo_aprobacion_id ?: $this->resolverFlujo($accion)?->id,
482	            'ciclo_anterior' => $esReenvio ? $nextCycle - 1 : null,
483	            'ciclo_nuevo' => $nextCycle,
