249	    /**
250	     * Convierte una colección [etapa, firma] (Proyecto::firmasParaFicha /
251	     * TieneFlujoPorEtapas::stepperDeAprobacion) en la forma plana que usa el
252	     * partial del stepper: ['nombre' => ..., 'estado' => aprobado|actual|pendiente|rechazado].
253	     */
254	    private function stepperEstados(Collection $filas): array
255	    {
256	        $actualMarcado = false;
257	
258	        return $filas->map(function (array $fila) use (&$actualMarcado): array {
259	            $firma = $fila['firma'];
260	            $estado = 'pendiente';
261	
262	            if ($firma?->estado_revision === 'Aprobado') {
263	                $estado = 'aprobado';
264	            } elseif ($firma?->estado_revision === 'Rechazado') {
265	                $estado = 'rechazado';
266	            } elseif (! $actualMarcado) {
267	                $estado = 'actual';
268	                $actualMarcado = true;
269	            }
270	
271	            return ['nombre' => $fila['etapa']->nombre, 'estado' => $estado];
272	        })->all();
273	    }
