275	    private function enfStepper(EnfAccion $accion): array
276	    {
277	        $proceso = EnfRevision::where('enf_accion_id', $accion->id)
278	            ->orderByDesc('id')
279	            ->value('proceso');
280	
281	        if (! $proceso) {
282	            return [];
283	        }
284	
285	        $actualMarcado = false;
286	
287	        return EnfRevision::where('enf_accion_id', $accion->id)
288	            ->where('proceso', $proceso)
289	            ->orderByDesc('revision_ciclo')
290	            ->orderByDesc('id')
291	            ->get()
292	            ->unique('flujo_aprobacion_etapa_id')
293	            ->sortBy('orden')
294	            ->values()
295	            ->map(function (EnfRevision $revision) use (&$actualMarcado): array {
296	                $estado = 'pendiente';
297	
298	                if ($revision->estado === 'APROBADO') {
299	                    $estado = 'aprobado';
300	                } elseif ($revision->estado === 'SUBSANACION') {
301	                    $estado = 'rechazado';
302	                } elseif (! $actualMarcado) {
303	                    $estado = 'actual';
304	                    $actualMarcado = true;
305	                }
306	
307	                return ['nombre' => $revision->etapa_nombre, 'estado' => $estado];
308	            })
309	            ->all();
310	    }
