        if ($this->existenFirmasDeCicloPorEtapa(
            (int) $firmaRechazada->flujo_aprobacion_id,
            (int) $firmaRechazada->revision_ciclo + 1,
            $documento
        )) {
            throw new \RuntimeException('Ya existe el siguiente ciclo de revisión para este registro.');
        }

        $ultimoCiclo = $this->ultimoCicloDeFirmasPorEtapa((int) $firmaRechazada->flujo_aprobacion_id, $documento);

        if ((int) $firmaRechazada->revision_ciclo !== $ultimoCiclo) {
            throw new \RuntimeException('La firma rechazada no pertenece al último ciclo de revisión.');
        }

        $firmasCiclo = $firmasCiclo ?: $this->firmasDeEtapasDelFlujo(
            (int) $firmaRechazada->flujo_aprobacion_id,
            (int) $firmaRechazada->revision_ciclo,
            $documento
        );

        if ($firmasCiclo->where('estado_revision', 'Rechazado')->count() !== 1) {
            throw new \RuntimeException('El ciclo de revisión contiene más de una etapa rechazada.');
        }
    }

    protected function firmasBaseParaNuevoCicloDesdeRechazo(FirmaProyecto $firmaRechazada, Collection $firmasCiclo): Collection
    {
        $plan = app(WorkflowResumptionPolicy::class)->plan(
            $firmasCiclo
                ->reject(fn (FirmaProyecto $firma): bool => $firma->estado_revision === 'Anulado')
                ->map(fn (FirmaProyecto $firma): array => [
                    'stage_id' => (int) $firma->flujo_aprobacion_etapa_id,
                    'order' => (int) $firma->orden_revision,
                    'status' => match ($firma->estado_revision) {
                        'Aprobado' => 'APPROVED',
                        'Rechazado' => 'REJECTED',
                        'Pendiente' => 'PENDING',
                        default => 'INVALID',
                    },
                    'source' => $firma,
                ])
                ->values()
        );

        $firmasBase = $plan->stages->pluck('source')->values();

        if ((int) $plan->rejectedStage['source']->id !== (int) $firmaRechazada->id) {
            throw new \RuntimeException('No se pudo preparar de forma segura el nuevo ciclo de revisión.');
        }

        return $firmasBase;
    }

    protected function validarAsignacionesParaNuevoCiclo(Collection $firmasBase, array $empleadosPorEtapa): Collection
    {
        $etapasRequeridas = $firmasBase
            ->pluck('flujo_aprobacion_etapa_id')
            ->map(fn ($id): int => (int) $id)
            ->values();

        $asignaciones = collect($empleadosPorEtapa)
            ->mapWithKeys(fn ($empleadoId, $etapaId): array => [(int) $etapaId => $empleadoId]);

        foreach ($asignaciones->keys() as $etapaId) {
            if (! $etapasRequeridas->contains((int) $etapaId)) {
                throw new \RuntimeException('Se indicó una asignación para una etapa que no pertenece al nuevo ciclo.');
            }
        }

        $empleados = collect();

        foreach ($firmasBase as $firmaBase) {
            $etapaId = (int) $firmaBase->flujo_aprobacion_etapa_id;
            $etapaNombre = $firmaBase->etapa_nombre ?: $firmaBase->etapa_codigo ?: $etapaId;

            if (! $asignaciones->has($etapaId)) {
                throw new \RuntimeException(sprintf('No se indicó un empleado para la etapa "%s".', $etapaNombre));
            }

            $empleadoId = $asignaciones->get($etapaId);

            if (! is_numeric($empleadoId) || (int) $empleadoId < 1) {
                throw new \RuntimeException(sprintf('El empleado indicado para la etapa "%s" no existe.', $etapaNombre));
            }

            $empleado = Empleado::withTrashed()->with('user')->find((int) $empleadoId);

            if (! $empleado || $empleado->trashed()) {
                throw new \RuntimeException(sprintf('El empleado indicado para la etapa "%s" no existe.', $etapaNombre));
            }

            $usuarioElegible = app(WorkflowResumptionPolicy::class)->eligibleRecipient(
                $empleado->user,
                $firmaBase->rol_requerido,
                true
            );

            if (! $usuarioElegible || (int) $usuarioElegible->empleado?->id !== (int) $empleado->id) {
                throw new \RuntimeException(sprintf(
                    'El revisor anterior de la etapa "%s" ya no es elegible; seleccione un reemplazo válido.',
                    $etapaNombre
                ));
            }

            $empleados->put($etapaId, $empleado);
        }

        return $empleados;
    }

    protected function validarNuevoCicloCreadoDesdeRechazo(
        FirmaProyecto $firmaRechazada,
        Collection $firmasBase,
        Collection $firmasCreadas,
        int $nuevoCiclo,
        int $cantidadCicloAnterior,
        ?DocumentoProyecto $documento = null
    ): void {
        $firmasNuevoCiclo = $this->firmasDeEtapasDelFlujo(
            (int) $firmaRechazada->flujo_aprobacion_id,
            $nuevoCiclo,
            $documento
        );

        if ($firmasNuevoCiclo->count() !== $firmasBase->count()
            || $firmasCreadas->count() !== $firmasBase->count()
            || $firmasNuevoCiclo->contains(fn (FirmaProyecto $firma): bool => $firma->estado_revision !== 'Pendiente')
            || $firmasNuevoCiclo->contains(fn (FirmaProyecto $firma): bool => (int) $firma->revision_ciclo !== $nuevoCiclo)
            || (int) $firmasNuevoCiclo->first()?->flujo_aprobacion_etapa_id !== (int) $firmasBase->first()?->flujo_aprobacion_etapa_id
        ) {
            throw new \RuntimeException('No se pudo preparar de forma segura el nuevo ciclo de revisión.');
        }

        $firmaActual = $this->firmaActualDeEtapasDelFlujo(
            (int) $firmaRechazada->flujo_aprobacion_id,
            $nuevoCiclo,
            $documento
        );

        if ((int) $firmaActual?->id !== (int) $firmasNuevoCiclo->first()?->id
            || $this->firmasDeEtapasCompletadas((int) $firmaRechazada->flujo_aprobacion_id, $nuevoCiclo, $documento)
        ) {
            throw new \RuntimeException('No se pudo preparar de forma segura el nuevo ciclo de revisión.');
        }

        $cantidadActualCicloAnterior = $this->firmasDeEtapasDelFlujo(
            (int) $firmaRechazada->flujo_aprobacion_id,
            (int) $firmaRechazada->revision_ciclo,
            $documento
        )->count();

        if ($cantidadActualCicloAnterior !== $cantidadCicloAnterior) {
            throw new \RuntimeException('No se pudo preparar de forma segura el nuevo ciclo de revisión.');
        }
    }

    protected function ultimoCicloDeFirmasPorEtapa(int $flujoAprobacionId, ?DocumentoProyecto $documento = null): int
    {
        return (int) $this->relacionFirmasDeEtapas($documento)
            ->where('flujo_aprobacion_id', $flujoAprobacionId)
            ->whereNotNull('flujo_aprobacion_etapa_id')
            ->whereNull('deleted_at')
            ->max('revision_ciclo');
<?php

namespace App\Services\Workflow;

use App\Models\User;
use Illuminate\Support\Collection;

final class WorkflowResumptionPolicy
{
    /**
     * @param  Collection<int, array{stage_id: int|string, order: int, status: string, source: mixed}>  $snapshots
     */
    public function plan(Collection $snapshots): WorkflowResumptionPlan
    {
        if ($snapshots->isEmpty()) {
            throw new \RuntimeException('El último ciclo no contiene etapas que puedan reanudarse.');
        }

        $ordered = $snapshots
            ->map(function (array $snapshot): array {
                foreach (['stage_id', 'order', 'status', 'source'] as $requiredKey) {
                    if (! array_key_exists($requiredKey, $snapshot)) {
                        throw new \InvalidArgumentException('La etapa histórica no contiene todos los datos requeridos.');
                    }
                }

                $snapshot['order'] = (int) $snapshot['order'];
                $snapshot['status'] = strtoupper((string) $snapshot['status']);

                if ($snapshot['order'] < 1 || ! in_array($snapshot['status'], ['APPROVED', 'REJECTED', 'PENDING'], true)) {
                    throw new \RuntimeException('La etapa histórica contiene un orden o estado no reconocido.');
                }

                return $snapshot;
            })
            ->sortBy([
                ['order', 'asc'],
                ['stage_id', 'asc'],
            ])
            ->values();

        if ($ordered->pluck('stage_id')->duplicates()->isNotEmpty()) {
            throw new \RuntimeException('El último ciclo contiene más de una revisión activa para la misma etapa.');
        }

        if ($ordered->pluck('order')->duplicates()->isNotEmpty()) {
            throw new \RuntimeException('El último ciclo contiene más de una etapa con el mismo orden.');
        }

        $rejectedStages = $ordered->where('status', 'REJECTED')->values();

        if ($rejectedStages->count() !== 1) {
            throw new \RuntimeException('El último ciclo debe contener exactamente una etapa en subsanación.');
        }

        $rejectedStage = $rejectedStages->first();

        foreach ($ordered as $stage) {
            if ($stage['order'] < $rejectedStage['order'] && $stage['status'] !== 'APPROVED') {
                throw new \RuntimeException('El ciclo contiene estados inconsistentes antes de la etapa en subsanación.');
            }

            if ($stage['order'] > $rejectedStage['order'] && $stage['status'] !== 'PENDING') {
                throw new \RuntimeException('El ciclo contiene estados inconsistentes después de la etapa en subsanación.');
            }
        }

        return new WorkflowResumptionPlan(
            $rejectedStage,
            $ordered->filter(fn (array $stage): bool => $stage['order'] >= $rejectedStage['order'])->values(),
        );
    }

    public function eligibleReviewer(?User $user, ?string $requiredRole = null, bool $requiresEmployee = false): ?User
    {
        if (! $user || ! $user->exists || $user->trashed()) {
            return null;
        }

        if ($requiredRole && ! $user->hasRole($requiredRole)) {
            return null;
        }

        if ($requiresEmployee) {
            $user->loadMissing('empleado');

            if (! $user->empleado || $user->empleado->trashed()) {
                return null;
            }
        }

        return $user;
    }

    public function eligibleRecipient(?User $user, ?string $requiredRole = null, bool $requiresEmployee = false): ?User
    {
        $eligible = $this->eligibleReviewer($user, $requiredRole, $requiresEmployee);

        if (! $eligible || blank($eligible->email) || ! filter_var($eligible->email, FILTER_VALIDATE_EMAIL)) {
            return null;
        }

        return $eligible;
    }
}
<?php

namespace App\Services\Proyecto;

use App\Models\Proyecto\FirmaProyecto;
use App\Models\Proyecto\FlujoAprobacionEtapa;
use App\Models\Proyecto\Proyecto;
use App\Models\User;
use App\Services\Workflow\WorkflowResumptionPolicy;
use Illuminate\Support\Collection;

class ProyectoWorkflowService
{
    public function etapas(Proyecto $proyecto, string $proceso, bool $soloActivas = true): Collection
    {
        $flujo = $proyecto->resolveFlujoAprobacion();

        if (! $flujo) {
            return collect();
        }

        $columna = $this->columnaAplicacion($proceso);

        return $flujo->etapas
            ->filter(fn (FlujoAprobacionEtapa $etapa): bool => (bool) $etapa->{$columna})
            ->when($soloActivas, fn (Collection $etapas): Collection => $etapas
                ->filter(fn (FlujoAprobacionEtapa $etapa): bool => (bool) $etapa->activo))
            ->sortBy([
                ['orden', 'asc'],
                ['id', 'asc'],
            ])
            ->values();
    }

    public function etapasInscripcion(Proyecto $proyecto): Collection
    {
        return $this->etapas($proyecto, Proyecto::FLUJO_INSCRIPCION);
    }

    public function etapasInformeIntermedio(Proyecto $proyecto): Collection
    {
        return $this->etapas($proyecto, Proyecto::FLUJO_INFORME_INTERMEDIO);
    }

    public function etapasCierre(Proyecto $proyecto): Collection
    {
        return $this->etapas($proyecto, Proyecto::FLUJO_CIERRE_PROYECTO);
    }

    public function primeraEtapa(Proyecto $proyecto, string $proceso): ?FlujoAprobacionEtapa
    {
        return $this->etapas($proyecto, $proceso)->first();
    }

    public function siguienteEtapa(
        Proyecto $proyecto,
        string $proceso,
        int $etapaActualId
    ): ?FlujoAprobacionEtapa {
        $etapas = $this->etapas($proyecto, $proceso);
        $indice = $etapas->search(fn (FlujoAprobacionEtapa $etapa): bool => $etapa->id === $etapaActualId);

        return $indice === false ? null : $etapas->get($indice + 1);
    }

    /**
     * @param  array<int|string, int|string>  $usuariosElegidosPorEtapa
     * @return array<int, int> empleado_id indexado por etapa_id
     */
    public function resolverEmpleados(
        Proyecto $proyecto,
        string $proceso,
        array $usuariosElegidosPorEtapa = []
    ): array {
        $resultado = [];

        foreach ($this->etapas($proyecto, $proceso) as $etapa) {
            if (! $etapa->cargo_firma_id) {
                throw new \RuntimeException(sprintf('La etapa "%s" no tiene cargo de firma configurado.', $etapa->nombre));
            }

            $usuario = $this->resolverUsuarioEtapa($etapa, $usuariosElegidosPorEtapa);
            $empleado = $usuario?->empleado;

            if (! $empleado || $empleado->trashed()) {
                throw new \RuntimeException(sprintf(
                    'No existe un responsable válido para la etapa "%s".',
                    $etapa->nombre
                ));
            }

            $resultado[$etapa->id] = $empleado->id;
        }

        return $resultado;
    }

    public function destinatariosSeleccionables(Proyecto $proyecto, string $proceso): Collection
    {
        $historicos = $this->destinatariosHistoricosNoElegibles($proyecto, $proceso);

        if ($historicos !== null) {
            return $historicos;
        }

        return $this->etapas($proyecto, $proceso)
            ->filter(fn (FlujoAprobacionEtapa $etapa): bool => (bool) $etapa->emisor_define_destinatario)
            ->mapWithKeys(function (FlujoAprobacionEtapa $etapa): array {
                $usuarios = $etapa->rolRevisor?->name
                    ? User::role($etapa->rolRevisor->name)
                        ->whereHas('empleado')
                        ->with('empleado')
                        ->orderBy('name')
                        ->get()
                    : collect();
                $usuarios = $usuarios
                    ->filter(fn (User $user): bool => filled($user->email) && filter_var($user->email, FILTER_VALIDATE_EMAIL))
                    ->values();

                return [$etapa->id => [
                    'etapa' => $etapa,
                    'usuarios' => $usuarios,
                ]];
            });
    }

    private function destinatariosHistoricosNoElegibles(Proyecto $proyecto, string $proceso): ?Collection
    {
        $tipoDocumento = match ($proceso) {
            Proyecto::FLUJO_INFORME_INTERMEDIO => 'Informe Intermedio',
            Proyecto::FLUJO_CIERRE_PROYECTO => 'Informe Final',
            default => null,
        };

        if (! $tipoDocumento) {
            return null;
        }

        $documento = $proyecto->documentos()
            ->where('tipo_documento', $tipoDocumento)
            ->latest('id')
            ->first();

        if (! $documento) {
            return null;
        }

        $ultimoCiclo = (int) $documento->firma_documento()
            ->whereNotNull('flujo_aprobacion_etapa_id')
            ->whereNull('deleted_at')
            ->max('revision_ciclo');
        $firmas = $documento->firma_documento()
            ->where('revision_ciclo', $ultimoCiclo)
            ->whereNotNull('flujo_aprobacion_etapa_id')
            ->whereNull('deleted_at')
            ->orderBy('orden_revision')
            ->get()
            ->reject(fn (FirmaProyecto $firma): bool => $firma->estado_revision === 'Anulado')
            ->values();

        if (! $firmas->contains(fn (FirmaProyecto $firma): bool => $firma->estado_revision === 'Rechazado')) {
            return null;
        }

        $plan = app(WorkflowResumptionPolicy::class)->plan(
            $firmas->map(fn (FirmaProyecto $firma): array => [
                'stage_id' => (int) $firma->flujo_aprobacion_etapa_id,
                'order' => (int) $firma->orden_revision,
                'status' => match ($firma->estado_revision) {
                    'Aprobado' => 'APPROVED',
                    'Rechazado' => 'REJECTED',
                    'Pendiente' => 'PENDING',
                    default => 'INVALID',
                },
                'source' => $firma,
            ])->values()
        );

        return $plan->stages
            ->filter(function (array $snapshot): bool {
                /** @var FirmaProyecto $firma */
                $firma = $snapshot['source'];
                $firma->loadMissing('empleado.user');

                return ! app(WorkflowResumptionPolicy::class)->eligibleRecipient(
                    $firma->empleado?->user,
                    $firma->rol_requerido,
                    true
                );
            })
            ->mapWithKeys(function (array $snapshot): array {
                /** @var FirmaProyecto $firma */
                $firma = $snapshot['source'];
                $etapa = $firma->flujoEtapa;

                if (! $etapa) {
                    $etapa = new FlujoAprobacionEtapa;
                    $etapa->forceFill([
                        'id' => $firma->flujo_aprobacion_etapa_id,
                        'orden' => $firma->orden_revision,
                        'codigo' => $firma->etapa_codigo,
                        'nombre' => $firma->etapa_nombre,
                    ]);
                }

                $usuarios = $firma->rol_requerido
                    ? User::role($firma->rol_requerido)->whereHas('empleado')->with('empleado')->orderBy('name')->get()
                    : User::query()->whereHas('empleado')->with('empleado')->orderBy('name')->get();
                $usuarios = $usuarios
                    ->filter(fn (User $user): bool => filled($user->email) && filter_var($user->email, FILTER_VALIDATE_EMAIL))
                    ->values();

                return [(int) $firma->flujo_aprobacion_etapa_id => [
                    'etapa' => $etapa,
                    'usuarios' => $usuarios,
                ]];
            });
    }

    public function inscripcionCompletada(Proyecto $proyecto): bool
    {
        $flujo = $proyecto->resolveFlujoAprobacion();
        $etapas = $this->etapasInscripcion($proyecto)
            ->filter(fn (FlujoAprobacionEtapa $etapa): bool => filled($etapa->cargo_firma_id))
            ->values();

        if (! $flujo || $etapas->isEmpty()) {
            return false;
        }

        $firmas = $proyecto->firma_proyecto()
            ->where('flujo_aprobacion_id', $flujo->id)
            ->whereIn('flujo_aprobacion_etapa_id', $etapas->pluck('id'))
            ->whereNull('deleted_at')
            ->orderByDesc('revision_ciclo')
            ->orderByDesc('id')
            ->get()
            ->groupBy('flujo_aprobacion_etapa_id');

        return $etapas->every(function (FlujoAprobacionEtapa $etapa) use ($firmas): bool {
            $ultimaDecisionVigente = $firmas->get($etapa->id, collect())
                ->reject(fn ($firma): bool => $firma->estado_revision === 'Anulado')
                ->first();

            return $ultimaDecisionVigente?->estado_revision === 'Aprobado';
        });
    }

