<?php

namespace App\Concerns;

use App\Http\Controllers\Docente\VerificarConstancia;
use App\Mail\EtapaFlujoPendiente;
use App\Mail\ProyectoEstadoCambiado;
use App\Models\Estado\TipoEstado;
