// ─── Anexo Methods (Step 9) ───────────────────────────────────────────────

public function uploadAnexo(): void
{
    $this->validate(['newAnexo' => 'required|file|max:10240']);
    $path = $this->newAnexo->store('anexos', 'public');
    $record = $this->ensureRecord();
    $record->anexos()->create(['documento_url' => $path]);
    $this->newAnexo = null;
    $this->anexosCount = $record->anexos()->count();
    Notification::make()->title('Anexo subido')->success()->send();
}

public function deleteAnexo(int $id): void
{
    if ($this->recordId) {
        $record = Proyecto::findOrFail($this->recordId);
        $record->anexos()->where('id', $id)->delete();
        $this->anexosCount = $record->anexos()->count();
    }
}

// ─── Student participacion updater ───────────────────────────────────────

public function updatedEstudianteProyecto($value, ?string $key = null): void
{
    if ($key === null || !str_ends_with($key, '.tipo_participacion_estudiante')) return;
    $index = (int) explode('.', $key, 2)[0];
    $tipo = $this->normalizeTipoParticipacionEstudiante($value) ?: (string) $value;
    $this->estudiante_proyecto[$index]['tipo_participacion_estudiante'] = $tipo;
    if (!$this->isTipoParticipacionAsignatura($tipo)) {
        $this->estudiante_proyecto[$index]['carrera_id'] = null;
        $this->estudiante_proyecto[$index]['asignatura_id'] = null;
        $this->estudiante_proyecto[$index]['periodo_academico_id'] = null;
    }
}

public function updateEstudianteTotal(int $i): void
{
    $h = (int)($this->estudiante_proyecto[$i]['cantidad_estudiantes_hombres'] ?? 0);
    $m = (int)($this->estudiante_proyecto[$i]['cantidad_estudiantes_mujeres'] ?? 0);
    $this->estudiante_proyecto[$i]['total_estudiantes'] = $h + $m;
}

// ─── Submit (Step 10) ─────────────────────────────────────────────────────

public function abrirModalEnviar(): void
{
    $this->autoGuardarBorrador();

    if (! $this->recordId) {
        Notification::make()->title('Error')->body('Complete al menos el primer paso antes de enviar.')->danger()->send();
        return;
    }

    $proyecto = Proyecto::find($this->recordId);

    if (! $proyecto) {
        Notification::make()->title('Error')->body('No se encontró el borrador del proyecto.')->danger()->send();
        return;
    }

    $this->modalEsReenvioSubsanacion = false;

    if ($this->reenviarAutomaticamenteTrasSubsanacion($proyecto)) {
        return;
    }

    $flujo = $proyecto->resolveFlujoAprobacion();

    if (! $flujo) {
        Notification::make()->title('Sin flujo configurado')->body('No hay flujo de aprobación configurado para este formulario. Contacte a administración.')->warning()->send();
        return;
    }

    $etapas = $proyecto->flujoEtapasActivasOrdenadas(Proyecto::FLUJO_INSCRIPCION);

    if ($etapas->isEmpty()) {
        Notification::make()->title('Sin etapas activas')->body('El flujo no tiene etapas activas configuradas.')->warning()->send();
        return;
    }

    $this->modalEtapasConDestinatario = $etapas
        ->filter(fn (FlujoAprobacionEtapa $etapa): bool => (bool) $etapa->emisor_define_destinatario)
        ->map(function (FlujoAprobacionEtapa $etapa): array {
            $candidatos = \App\Models\User::with('roles')
                ->when($etapa->rol_revisor_id, fn ($q) => $q->whereHas('roles', fn ($r) => $r->where('roles.id', $etapa->rol_revisor_id)))
                ->whereHas('empleado')
                ->orderBy('name')
                ->get()
                ->filter(fn (\App\Models\User $user): bool => filled($user->email) && filter_var($user->email, FILTER_VALIDATE_EMAIL))
                ->map(fn (\App\Models\User $user): array => [
                    'user_id' => $user->id,
                    'nombre' => $user->name,
                ])
                ->values()
                ->toArray();

            return [
                'id' => $etapa->id,
                'nombre' => $etapa->nombre,
                'codigo' => $etapa->codigo ?? null,
                'orden' => $etapa->orden,
                'rol_nombre' => $etapa->rolRevisor?->name ?? null,
                'candidatos' => $candidatos,
            ];
        })
        ->values()
        ->toArray();

    $this->modalDestinatarios = [];
    $this->modalStep = 0;
    $this->showEnviarModal = true;
}

/**
 * Si el proyecto ya venía de un flujo de firmas por etapas y fue devuelto a
 * Subsanación, el destinatario ya está definido por el ciclo anterior: se
 * reenvía directamente al mismo firmante, sin pedir que se configure de nuevo.
 */
private function reenviarAutomaticamenteTrasSubsanacion(Proyecto $proyecto): bool
{
    $firmaRechazada = $this->firmaRechazadaActualPorEtapa($proyecto);

    if (! $firmaRechazada) {
        return false;
    }

    $user = auth()->user();

    if (! $user) {
        Notification::make()->title('Error')->body('No tiene autorización para reenviar este registro.')->danger()->send();
        return true;
    }

    $this->validarFormularioAntesDeEnviar();

    $etapasConReemplazo = $this->etapasQueRequierenReemplazoParaReenvio($firmaRechazada);

    if ($etapasConReemplazo->isNotEmpty()) {
        $this->modalEtapasConDestinatario = $etapasConReemplazo
            ->map(function (array $etapa): array {
                $etapa['candidatos'] = \App\Models\User::query()
                    ->when($etapa['rol_nombre'], fn ($query) => $query->whereHas(
                        'roles',
                        fn ($roles) => $roles->where('roles.name', $etapa['rol_nombre'])
                    ))
                    ->whereHas('empleado')
                    ->orderBy('name')
                    ->get()
                    ->filter(fn (\App\Models\User $user): bool => filled($user->email) && filter_var($user->email, FILTER_VALIDATE_EMAIL))
                    ->map(fn (\App\Models\User $user): array => [
                        'user_id' => $user->id,
                        'nombre' => $user->name,
                    ])
                    ->values()
                    ->all();

                return $etapa;
            })
            ->all();
        $this->modalDestinatarios = [];
        $this->modalStep = 0;
        $this->modalEsReenvioSubsanacion = true;
        $this->showEnviarModal = true;

        return true;
    }

    try {
        $this->reenviarDesdeSubsanacionPorEtapa(
            $firmaRechazada,
            $user,
            $this->empleadosPorEtapaParaReenvio($firmaRechazada)
        );
    } catch (\Exception $e) {
        Notification::make()->title('Error al enviar')->body($e->getMessage())->danger()->send();
        return true;
    }

    try {
        Mail::to($user->email)->send(new ProyectoCreado($proyecto, $user));
    } catch (\Exception $e) {
        \Log::warning($e->getMessage());
    }

    Notification::make()->title('Proyecto reenviado a revisión')->success()->send();
    redirect()->route('proyectosDocente');

    return true;
}

protected function proyectoEsperadoIdParaReenvio(): ?int
{
    return $this->recordId;
}

public function modalSiguiente(): void
{
    $this->modalStep++;
}

public function modalAnterior(): void
{
    $this->modalStep = max(0, $this->modalStep - 1);
}

public function confirmarEnvio(): void
{
    if (! $this->validarFormularioAntesDeEnviar()) {
        $this->showEnviarModal = false;
        return;
    }

    $proyecto = Proyecto::findOrFail($this->recordId);

    try {
        if ($this->modalEsReenvioSubsanacion) {
            $firmaRechazada = $this->firmaRechazadaActualPorEtapa($proyecto);

            if (! $firmaRechazada || ! auth()->user()) {
                throw new \RuntimeException('No se pudo identificar la etapa que debe reanudarse.');
            }

            $this->reenviarDesdeSubsanacionPorEtapa(
                $firmaRechazada,
                auth()->user(),
                $this->empleadosPorEtapaParaReenvio($firmaRechazada, $this->modalDestinatarios)
            );
        } else {
            $this->enviarPorFlujoDeEtapas($proyecto);
        }
    } catch (\Exception $e) {
        Notification::make()->title('Error al enviar')->body($e->getMessage())->danger()->send();
        return;
    }

    $this->showEnviarModal = false;
    $esReenvio = $this->modalEsReenvioSubsanacion;
    $this->modalEsReenvioSubsanacion = false;

    try {
        Mail::to(auth()->user()->email)->send(new ProyectoCreado($proyecto, auth()->user()));
    } catch (\Exception $e) {
        \Log::warning($e->getMessage());
    }

    Notification::make()->title($esReenvio ? 'Proyecto reenviado a revisión' : 'Proyecto enviado a firmar')->success()->send();
    redirect()->route('proyectosDocente');
}

private function enviarPorFlujoDeEtapas(Proyecto $proyecto): void
{
    $flujo = $proyecto->resolveFlujoAprobacion();

    if (! $flujo) {
        throw new \RuntimeException('No hay flujo de aprobación configurado para este proyecto.');
    }

    // Lock-in: atamos el proyecto a este flujo para que cambios futuros no lo afecten.
    if (! $proyecto->flujo_aprobacion_id) {
        $proyecto->flujo_aprobacion_id = $flujo->id;
        $proyecto->saveQuietly();
    }

    $etapas = $this->etapasActivasParaEnvioPorFlujo($proyecto);

    $empleadosPorEtapa = [];

    foreach ($etapas as $etapa) {
    $tipoEstadoPrimera = $primeraFirma?->cargo_firma()->value('tipo_estado_id');
    $estadoActualId = $proyecto->fresh()->estado?->tipo_estado_id;

    if ($firmas->contains(fn (FirmaProyecto $firma): bool => $firma->estado_revision !== 'Pendiente')
        || $firmas->contains(fn (FirmaProyecto $firma): bool => (int) $firma->revision_ciclo !== 1)
        || $idsEtapa->count() !== $idsEtapa->unique()->count()
        || ! $primeraFirma
        || ! $tipoEstadoPrimera
        || (int) $estadoActualId !== (int) $tipoEstadoPrimera
        || $proyecto->firmasDeEtapasCompletadas((int) $flujo->id, 1)
    ) {
        throw new RuntimeException('No se pudo preparar el envio por etapas de forma segura.');
    }

    foreach ($firmas as $firma) {
        $esPrimera = (int) $firma->id === (int) $primeraFirma->id;

        if ($proyecto->firmaEsActualEnFlujoPorEtapa($firma) !== $esPrimera) {
            throw new RuntimeException('No se pudo preparar el envio por etapas de forma segura.');
        }
    }
}


protected function etapasActivasParaEnvioPorFlujo(Proyecto $proyecto): Collection
{
    $etapas = $proyecto
        ->flujoEtapasActivasOrdenadas(Proyecto::FLUJO_INSCRIPCION)
        ->values();

    if ($etapas->isEmpty()) {
        throw new RuntimeException('No hay etapas activas configuradas para enviar este proyecto a revisión.');
    }

    $etapas->each(function (FlujoAprobacionEtapa $etapa): void {
        if (! $etapa->cargo_firma_id) {
            throw new RuntimeException(sprintf('La etapa "%s" no tiene cargo de firma configurado.', $etapa->nombre));
        }

        if (! $etapa->rol_revisor_id && ! $etapa->usuario_responsable_id) {
            throw new RuntimeException(sprintf('La etapa "%s" no tiene rol revisor ni responsable configurado.', $etapa->nombre));
        }
    });

    return $etapas;
}

protected function loadFirmasFromRecord(Proyecto $record): void
{
    // No-op: firmas are now handled by the workflow modal.
}

public function borrador(): void
{
    $this->autoGuardarBorrador();

    if (!$this->recordId) {
        Notification::make()->title('Error')->body('Complete al menos el primer paso.')->danger()->send();
        return;
    }
    $record = Proyecto::findOrFail($this->recordId);
    $empleado = auth()->user()->empleado;
    $estadoConservado = $record->estadoDespuesDeGuardar();

    try {
        $record->agregarFirma(cargoFirma: 'Coordinador Proyecto', empleado: $empleado);

        if ($estadoConservado === 'Subsanacion') {
            activity('Proyecto')
                ->performedOn($record)
                ->causedBy(auth()->user())
                ->withProperties(['estado_conservado' => $estadoConservado])
                ->log('Cambios guardados durante la subsanación.');
        }
    } catch (\Exception $e) {
        Notification::make()->title('Error')->body($e->getMessage())->danger()->send();
        return;
    }

    Notification::make()
        ->title($estadoConservado === 'Subsanacion' ? 'Cambios de subsanación guardados' : 'Borrador guardado')
        ->success()
        ->send();
    redirect()->route('proyectosDocente');
}

// ─── Normalization helpers ────────────────────────────────────────────────

protected function dateForInput(mixed $value): string
{
    if (empty($value)) return '';
    try {
        if ($value instanceof \DateTimeInterface) return $value->format('Y-m-d');
        return Carbon::parse($value)->format('Y-m-d');
    } catch (\Throwable) {
        return '';
    }
}

